<?php
declare(strict_types=1);
require __DIR__.'/../vendor/autoload.php';
use Magebean\Engine\{RequirementCatalog,RequirementProfileCatalog,RequirementPolicy,MagebeanFindingSemantics};
$root=dirname(__DIR__);$catalog=RequirementCatalog::read('magebean-catalog')['requirements'];$profiles=RequirementProfileCatalog::all();$groups=[];
foreach($catalog as $r)$groups[$r['control']][]=$r;ksort($groups,SORT_NATURAL);
$labels=[];foreach(glob($root.'/src/Rules/controls/*.json') as $file){$c=json_decode(file_get_contents($file),true,512,JSON_THROW_ON_ERROR);$labels[$c['control']]=$c['title'];}
$lines=['# Magebean Security Baseline v1','','**Author:** Son Cao','**Baseline version:** 1','**Documentation revision:** 2026-11-12','**Scope:** '.count($catalog).' active Magebean requirements','','## Scope and authority','','This baseline mirrors the current [Magebean catalogue](../src/Rules/requirements/magebean-catalog.json). It covers observed technical weaknesses in collected Magento store, source, dependency and deployment state. A finding must identify what was observed and where, why it matters, its uncertainty, and how to remediate and verify it. A bounded current-state snapshot does not certify every business flow or overall security.','','ASVS and PCI DSS are separate source families; their official clauses are outside this baseline. The combined runtime catalogue contains 110 Magebean, 345 ASVS and 280 PCI requirements. See [source families](reference/requirement-source-families.md).','','## Interpretation','','- One stable MB identity owns one assessment definition, with reusable checks and explicit evidence obligations. Criterion, revision, applicability, limitations and check arguments remain authoritative in the catalogue.','- Category distinguishes security, correctness, explicit policy and informational observations. Confirmed evidence is not confirmed exploitation. Typed detector results may refine the default category shown here.','- Severity below is catalogue priority; projected policy/maintenance priority and explicit project overrides are described in [findings and output](guides/findings-and-output.md).','- Missing data, unsupported expressions and collection budgets remain diagnostics. They do not prove a vulnerability or PASS. Unavailable/excluded package lists are not appended to actionable issue messages.','- Exact shared evidence may produce one canonical issue with several contributing rule IDs. Raw assessment outcomes and historical identities are retained. MB-0731 remains an explicit compatible selector; built-in profiles use MB-0728.','- The historical 60-rule retirement archive remains intact: 10 scoped automated revisions are now active and 50 references remain inactive. Inactivity is an evidence-based implementation decision, not proof that automation is impossible.','','## Profile selection','','Membership counts are inventory, not issue counts or completed coverage. Default LOCAL selection assumes no project overrides or additional filters. Additional context selects a check; the check must still collect actual evidence. Hardening selects all six strict native-API policies by default, and retains six separately gated machine/deployment checks. Development is offline by default. Evidence is opt-in record lint.','','| Profile | Inventory | Default LOCAL selection | Default context |','|---|---:|---:|---|'];
foreach($profiles as $key=>$p){if(($p['family']??null)!=='magebean')continue;$pack=RequirementCatalog::forProfile($key);$selected=count(array_filter($pack['rules'],static fn(array $r):bool=>!RequirementPolicy::requiresHuman($r)));$lines[]='| `'.$key.'` | '.count($p['requirement_ids']).' | '.$selected.' | '.implode(', ',array_map(static fn(string $v):string=>'`'.$v.'`',$p['default_capabilities']??[])).' |';}
array_push($lines,'','Use [profiles](guides/profiles.md), [production context](guides/production-context.md) and the [CLI reference](guides/cli-reference.md) for selection and required inputs. The CLI summary reports selected rules and context/filter omissions; it does not label selection as completed coverage.','','## Rule groups','','| Control | Rules |','|---|---:|');
foreach($groups as $id=>$rules)$lines[]='| '.$id.' — '.($labels[$id]??$id).' | '.count($rules).' |';
$lines[]='| **Total Magebean rules** | **'.count($catalog).'** |';
array_push($lines,'','## Magebean requirement inventory','','Native profile membership below is persisted membership before context, target-mode and manual filters. No membership means the rule remains available through an explicit compatible selector, subject to its applicability gates.');
foreach($groups as $control=>$rules){$lines[]='';$lines[]='### '.$control.' — '.($labels[$control]??$control);usort($rules,static fn(array $a,array $b):int=>strcmp($a['id'],$b['id']));foreach($rules as $r){$members=[];foreach($profiles as $key=>$p)if(($p['family']??null)==='magebean'&&in_array($r['id'],$p['requirement_ids'],true))$members[]=$key;$semantic=MagebeanFindingSemantics::profile($r['id']);array_push($lines,'','#### '.$r['id'].' — '.$r['title'],'','- **Revision:** '.$r['revision'],'- **Criterion:** '.$r['criterion'],'- **Catalogue severity:** '.$r['severity'],'- **Default finding category:** '.$semantic['category'],'- **Catalogue coverage:** '.($r['coverage']??'AUTOMATED'),'- **Target modes:** '.implode(', ',$r['target_modes']),'- **Native profiles:** '.($members?implode(', ',$members):'None; explicit selection only'));if(isset($r['applicability']['capability']))$lines[]='- **Context capability:** `'.$r['applicability']['capability'].'`';}}
array_push($lines,'','## Maintenance','','Generated from current runtime catalogues by `php tools/update-baseline-doc.php`. Run with `--check` to detect drift without writing. Historical QA, plans and migration evidence live under [archive](archive/README.md); they do not override this baseline or current profiles.');
$text=implode("\n",$lines)."\n";$path=$root.'/docs/magebean-baseline-v1.md';
if(in_array('--check',$argv,true)){if(!is_file($path)||file_get_contents($path)!==$text)throw new RuntimeException('Baseline documentation is stale; run php tools/update-baseline-doc.php.');echo "Baseline documentation matches 110 active Magebean rules and current profiles.\n";}else{file_put_contents($path,$text);echo "Updated ",$path,"\n";}
